// Reference solution
function hopHeaders(src, routers, dst) {
  var out = [];
  for (var i = 0; i <= routers.length; i++) {
    out.push({ srcMac: i === 0 ? src.mac : routers[i - 1].outMac, dstMac: i === routers.length ? dst.mac : routers[i].inMac, srcIp: src.ip, dstIp: dst.ip });
  }
  return out;
}
